// src/core/Random.ts
var Random = class {
  constructor(seed) {
    this.seed = seed;
    this.state = seed >>> 0;
  }
  /** [0, 1) */
  next() {
    this.state = this.state + 1831565813 >>> 0;
    let t = this.state;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
  /** [0, n) 的整数 */
  int(n) {
    return Math.floor(this.next() * n);
  }
  /** [min, max) */
  range(min, max) {
    return min + (max - min) * this.next();
  }
};
var lobbyRng = new Random(Date.now());

// src/battle/Arena.ts
var SIDES = 8;
var Arena = class {
  constructor(radius = GAME.arena.radius, cy = GAME.arena.cy) {
    this.radius = radius;
    this.cy = cy;
    this.cx = GAME.arena.cx;
    /** 各边外法线（单位向量）。顶点在 22.5°+45°k，边的法线在 45°k */
    this.normals = [];
    this.apothem = radius * Math.cos(Math.PI / SIDES);
    for (let k = 0; k < SIDES; k++) {
      const a = k * 2 * Math.PI / SIDES;
      this.normals.push({ nx: Math.cos(a), ny: Math.sin(a) });
    }
  }
  /** 圆（半径 r）是否完全在场内 */
  contains(x, y, r = 0) {
    for (const { nx, ny } of this.normals) {
      if ((x - this.cx) * nx + (y - this.cy) * ny + r > this.apothem) return false;
    }
    return true;
  }
  /**
   * 墙壁碰撞：把穿墙的圆推回场内并反射速度。
   * 返回是否撞墙。
   */
  collide(b) {
    let hit = false;
    for (const { nx, ny } of this.normals) {
      const over = (b.x - this.cx) * nx + (b.y - this.cy) * ny + b.radius - this.apothem;
      if (over > 0) {
        b.x -= nx * over;
        b.y -= ny * over;
        const vn = b.vx * nx + b.vy * ny;
        if (vn > 0) {
          b.vx -= 2 * vn * nx;
          b.vy -= 2 * vn * ny;
        }
        hit = true;
      }
    }
    return hit;
  }
  /** 描出八边形路径 */
  path(ctx) {
    ctx.beginPath();
    for (let k = 0; k < SIDES; k++) {
      const a = (k + 0.5) * 2 * Math.PI / SIDES;
      const px = this.cx + Math.cos(a) * this.radius;
      const py = this.cy + Math.sin(a) * this.radius;
      if (k === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }
};

