var Swordsman = class extends Ball {
  constructor(cfg, x, y, angle) {
    super(cfg, x, y, angle);
    this.cfg = cfg;
    this.cooldown = 0;
    /** 已经掷过反弹概率的箭（每支箭只掷一次） */
    this.rolled = /* @__PURE__ */ new WeakSet();
    this.angle = angle;
  }
  /** 剑身上的判定点（从剑柄到剑尖均匀取 3 点） */
  blade() {
    const { bladeStart, bladeLen } = this.cfg;
    return [0, 0.5, 1].map((k) => {
      const d = bladeStart + bladeLen * k;
      return { x: this.x + Math.cos(this.angle) * d, y: this.y + Math.sin(this.angle) * d };
    });
  }
  act(dt, world) {
    this.angle += this.cfg.spinSpeed * dt;
    this.cooldown = Math.max(0, this.cooldown - dt);
    const blade = this.blade();
    const w = this.cfg.bladeWidth;
    for (const p of world.projectiles) {
      if (p.dead || p.owner === this) continue;
      if (!blade.some((b) => Math.hypot(b.x - p.x, b.y - p.y) < w + p.radius)) continue;
      if (this.rolled.has(p)) continue;
      this.rolled.add(p);
      if (world.rng.next() >= this.cfg.reflectChance) continue;
      const back = p.owner;
      const speed = Math.hypot(p.vx, p.vy);
      const a = Math.atan2(back.y - p.y, back.x - p.x);
      p.vx = Math.cos(a) * speed;
      p.vy = Math.sin(a) * speed;
      p.owner = this;
      p.color = this.color;
      world.events.push({ type: "wall" });
    }
    if (this.cooldown > 0) return;
    for (const e of world.enemies(this)) {
      if (!blade.some((b) => Math.hypot(b.x - e.x, b.y - e.y) < w + e.radius)) continue;
      e.takeDamage(this.cfg.damage, world, "melee", this);
      this.damageDealt += this.cfg.damage;
      this.hits++;
      this.cooldown = this.cfg.cooldown;
      return;
    }
  }
  draw(ctx) {
    super.draw(ctx);
    const { bladeStart, bladeLen } = this.cfg;
    const c = Math.cos(this.angle);
    const s = Math.sin(this.angle);
    ctx.lineCap = "round";
    ctx.strokeStyle = "#8a6d3b";
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(this.x + c * bladeStart - s * 10, this.y + s * bladeStart + c * 10);
    ctx.lineTo(this.x + c * bladeStart + s * 10, this.y + s * bladeStart - c * 10);
    ctx.stroke();
    ctx.strokeStyle = "#e8eef5";
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.moveTo(this.x + c * bladeStart, this.y + s * bladeStart);
    ctx.lineTo(this.x + c * (bladeStart + bladeLen), this.y + s * (bladeStart + bladeLen));
    ctx.stroke();
    ctx.lineCap = "butt";
  }
};

// src/battle/characters/Vampire.ts
var Vampire = class extends Ball {
  constructor(cfg, x, y, angle) {
    super(cfg, x, y, angle);
    this.cfg = cfg;
    this.cooldown = 0;
    /** 獠牙朝向（始终朝着敌人） */
    this.aim = 0;
    /** 当前被我吸住的对象（供绘制连线用） */
    this.grabbedTarget = null;
    /** 放开后必须先分开再碰到才能再吸（不是时间冷却） */
    this.ignore = null;
  }
  /** 第 i 颗獠牙（0/1）的中心坐标与朝向 */
  fang(i) {
    const spread = this.cfg.fangSpreadDeg * Math.PI / 180;
    const a = this.aim + (i === 0 ? -spread / 2 : spread / 2);
    return {
      x: this.x + Math.cos(a) * this.cfg.fangOrbit,
      y: this.y + Math.sin(a) * this.cfg.fangOrbit,
      a
    };
  }
  grab(enemy, world) {
    if (this.grabbedTarget || enemy.grabbedBy || this.ignore === enemy) return;
    if (world.initiatorOf(this, enemy) === enemy) return;
    enemy.grabbedBy = this;
    enemy.grabTimer = this.cfg.grabDuration;
    this.grabbedTarget = enemy;
  }
  /** 吸住对方期间吸血鬼自己也不动 */
  canMove(world) {
    return !world.enemies(this).some((e) => e.grabbedBy === this);
  }
  act(dt, world) {
    this.cooldown = Math.max(0, this.cooldown - dt);
    const enemies = world.enemies(this);
    const prev = this.grabbedTarget;
    this.grabbedTarget = enemies.find((e) => e.grabbedBy === this) ?? null;
    const focus = this.grabbedTarget ?? world.enemyOf(this);
    this.aim = Math.atan2(focus.y - this.y, focus.x - this.x);
    if (prev && !this.grabbedTarget && !prev.dead) {
      this.ignore = prev;
      const dx = prev.x - this.x;
      const dy = prev.y - this.y;
      const d = Math.hypot(dx, dy) || 1;
      prev.vx = dx / d * prev.speed;
      prev.vy = dy / d * prev.speed;
      this.vx = -dx / d * this.speed;
      this.vy = -dy / d * this.speed;
    }
    if (this.ignore) {
      const far = Math.hypot(this.ignore.x - this.x, this.ignore.y - this.y) > this.radius + this.ignore.radius + 4;
      if (this.ignore.dead || far) this.ignore = null;
    }
    for (const e of enemies) {
      if (Math.hypot(e.x - this.x, e.y - this.y) < this.radius + e.radius) this.grab(e, world);
    }
    if (this.cooldown > 0) return;
    for (const e of enemies) {
      for (let i = 0; i < 2; i++) {
        const f = this.fang(i);
        if (Math.hypot(e.x - f.x, e.y - f.y) < e.radius + this.cfg.fangRadius) {
          e.takeDamage(this.cfg.damage, world, "melee", this);
          this.damageDealt += this.cfg.damage;
          this.hits++;
          this.heal(Math.round(this.cfg.damage * this.cfg.lifesteal), world);
          this.cooldown = this.cfg.cooldown;
          this.grab(e, world);
          return;
        }
      }
    }
  }
  draw(ctx) {
    const t = this.grabbedTarget;
    if (t) {
      ctx.strokeStyle = "#ff4d6d";
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(this.x, this.y);
      ctx.lineTo(t.x, t.y);
      ctx.stroke();
    }
    super.draw(ctx);
    const r = this.cfg.fangRadius;
    for (let i = 0; i < 2; i++) {
      const f = this.fang(i);
      ctx.save();
      ctx.translate(f.x, f.y);
      ctx.rotate(f.a);
      ctx.fillStyle = "#fff";
      ctx.strokeStyle = "#8b0000";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(r, 0);
      ctx.lineTo(-r * 0.8, -r * 0.55);
      ctx.lineTo(-r * 0.8, r * 0.55);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    }
  }
};

